mapper.sql:
from mst_cust c

    and c.cust_cd like #{q.custCdLike} escape '\'
    and c.cust_nm ilike #{q.custNmLike} escape '\'
    and c.cust_type = #{q.custType}
    and c.use_yn = #{q.useYn}

mapper.update:
update mst_cust
   set cust_cd = #{f.custCd}, cust_nm = #{f.custNm}, cust_type = #{f.custType}, biz_no = #{f.bizNo},
       ceo_nm = #{f.ceoNm}, tel = #{f.tel}, email = #{f.email}, addr = #{f.addr}, remark = #{f.remark},
       use_yn = #{f.useYn}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where cust_id = #{id} and row_ver = #{f.rowVer}

update mst_cust_contact
   set contact_nm = #{c.contactNm}, dept_nm = #{c.deptNm}, tel = #{c.tel}, email = #{c.email},
       main_yn = #{c.mainYn}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where contact_id = #{c.contactId} and cust_id = #{custId} and use_yn = 'Y' and row_ver = #{c.rowVer}
